/// <summary>
/// CB788_CustomPricingComponents
/// Price component table
/// </summary>
public class METSalesLinePriceComponent extends common
{
}

Method.Source:
    /// <summary>
    /// Find a price component record
    /// </summary>
    /// <param name = "_inventTransId">The <c>InventTransId</c> value to retrieve the price component record.</param>
    /// <param name = "_component">The <c>METComponent</c> value to retrieve the price component record.</param>
    /// <param name = "_priceCodeRef">The <c>METComponent</c> value to retrieve the price component record.</param>
    /// <param name = "_forUpdate">Specifies if record is selected for update</param>
    /// <returns>Found price component record; otherwise, blank.</returns>
    static METSalesLinePriceComponent find(InventTransId _inventTransId,
                                           METComponent  _component,
                                           METPriceCodeRef _priceCodeRef,
                                           boolean       _forUpdate = false)
    {
        METSalesLinePriceComponent priceComponent;

        if (_inventTransId && _component)
        {
            if (_forUpdate)
            {
                priceComponent.selectForUpdate(_forUpdate);
            }

            select firstonly priceComponent
                       where priceComponent.InventTransId == _inventTransId
                          && priceComponent.Component     == _component
                          && priceComponent.PriceCodeRef  == _priceCodeRef;
        }

        return priceComponent;
    }

/// <summary>
///    Checks whether a price component record exists.
/// </summary>
/// <param name="_inventTransId">
///    The <c>InventTransId</c> value to retrieve the price component record.
/// </param>
/// <param name="_component">
///    The <c>METComponent</c> value to retrieve the price component record.
/// </param>
/// <param name = "_priceCodeRef">The <c>METComponent</c> value to retrieve the price component record.</param>
/// <returns>
///    true if the price component record exists; otherwise, false.
/// </returns>
static boolean exist(InventTransId _inventTransId, METComponent _component, METPriceCodeRef _priceCodeRef)
{
    return _inventTransId &&
           _component &&
           (select firstonly RecId from METSalesLinePriceComponent
                                  where METSalesLinePriceComponent.InventTransId == _inventTransId
                                     && METSalesLinePriceComponent.Component == _component
                                     && METSalesLinePriceComponent.PriceCodeRef == _priceCodeRef).RecId != 0;
}

    /// <summary>
    /// Sum vendor value for all price component detail lines of the price component.
    /// </summary>
    /// <returns>
    /// Total vendor value amount of all price component detail lines.
    /// </returns>
    public Amount getTotalVendorValue()
    {
        METSalesLinePriceComponentDetail priceComponentDetail;

        select sum(VendorValue) from priceComponentDetail
            where priceComponentDetail.InventTransId == this.InventTransId
               && priceComponentDetail.Component == this.Component;

        return priceComponentDetail.VendorValue;
    }

    /// <summary>
    /// Validatevalue Method on table
    /// </summary>
    /// <returns>return the result</returns>
    public Description validateValue()
    {
        Description error;

        if (METComponentCode::findComponent(this.Component).RecId == 0)
        {
            error = strFmt("@MET:METInvalidComponent", this.Component);
        }

        return Error;
    }

    /// <summary>
    /// Validatewrite Method on table
    /// </summary>
    /// <returns>return the result</returns>
    public boolean validateWrite()
    {
        boolean ret = true;
        
        ret = super();

        if (this.validateValue() != '')
        {
            ret = false;
        }

        return ret;
    }
